"""ext2/3/4 boyutlandirma — saf Python (cevrimdisi `resize2fs` karsiligi).

Neden: ext boyutlandirmasi daha once yalnizca Windows'un `Resize-Partition`
aracina yonlendiriliyordu; o arac ext'i tanimadigi icin ext bolumu **hicbir
platformda** buyutulemiyordu (kullanici bildirimi, 2026-09-29).

## Buyutme
1. Son grup yarim ise bitmap'inde yeni bloklar bosaltilir.
2. Yeni gruplar eklenir; her grubun bitmap'leri ve inode tablosu **kendi
   icine** yerlestirilir (flex_bg birimde de gecerli bir yerlesimdir).
3. GDT buyumesi gerekiyorsa:
   * `resize_inode` varsa ayrilmis GDT bloklari kullanilir ve inode 7
     yeniden kurulur (e2fsprogs `ext2fs_create_resize_inode` ile ayni duzen);
   * ayrilmis blok yetmezse birim `meta_bg`ye gecirilir (`resize2fs` de
     boyle yapar): eski GDT bloklari `s_first_meta_bg` olur, yeni bloklar
     meta gruplarinin 0./1./son grubunda durur.
4. Ustblok ve tum yedekleri, GDT'nin tum kopyalari yazilir.

Yazma sirasi: once yeni gruplarin metaverisi (eski birimin disinda), sonra
GDT kopyalari, **en son** birincil ustblok. Yarida kesilirse birim eski
boyutuyla tutarli kalir.

## Kucultme
Kesilen bolgedeki bloklar ve inode'lar kullanilmiyorsa dogrudan yapilir;
kullaniliyorsa once `extmove` ile tasinir.

## Reddedilenler (nedeniyle)
`bigalloc`, ayri gunluk aygiti, `mmp`, `sparse_super2`, gunlugu
tekrar oynatilmamis (temiz kapatilmamis) birim.

Dogrulama: `tests/ext_resize_check.py` — mkfs.ext4 ve kendi bicimlendiricimizin
urettigi birimler buyutulur/kucultulur, her adimda `e2fsck -fn` temiz ve
dosya icerikleri ayni kalmali.
"""
from __future__ import annotations

import struct
import time
from typing import Callable, Dict, List, Optional, Tuple

from .extlayout import (BG_BLOCK_UNINIT, BG_INODE_UNINIT,
                        COMPAT_RESIZE_INODE, COMPAT_SPARSE_SUPER2,
                        GD_BLOCK_BITMAP, GD_FLAGS, GD_FREE_BLOCKS,
                        GD_FREE_INODES, GD_INODE_BITMAP, GD_INODE_TABLE,
                        GD_ITABLE_UNUSED, GD_USED_DIRS, INCOMPAT_64BIT,
                        INCOMPAT_JOURNAL_DEV, INCOMPAT_META_BG, INCOMPAT_MMP,
                        INCOMPAT_RECOVER, RO_BIGALLOC, SUPERBLOCK_OFFSET,
                        ExtCsum, ExtGeometry, desc_field, set_desc_field)
from .image import BlockDevice
from ..i18n import tr

INO_RESIZE = 7
MIN_LAST_GROUP_FREE = 50         # resize2fs ile ayni: son grup bundan kucukse atilir


class ExtResizeError(Exception):
    pass


Progress = Optional[Callable[[str, int], None]]


# ======================================================================
# Birim durumu (ustblok + tum tanimlayicilar bellekte)
# ======================================================================
class _Volume:
    def __init__(self, dev: BlockDevice):
        self.dev = dev
        sb = dev.read(SUPERBLOCK_OFFSET, 1024)
        if len(sb) < 1024 or struct.unpack_from("<H", sb, 0x38)[0] != 0xEF53:
            raise ExtResizeError(tr("ext imzasi yok"))
        self.geo = ExtGeometry(sb)
        self.csum = ExtCsum(self.geo)
        g = self.geo
        self.bs = g.block_size
        self.descs: List[bytearray] = []
        for group in range(g.group_count):
            off = g.descriptor_offset(group)
            self.descs.append(bytearray(dev.read(off, g.desc_size)))

    # --- ham blok -----------------------------------------------------
    def read_block(self, block: int) -> bytearray:
        return bytearray(self.dev.read(block * self.bs, self.bs))

    def write_block(self, block: int, data: bytes) -> None:
        if len(data) != self.bs:
            raise ExtResizeError(tr("Blok boyutu uyusmuyor"))
        self.dev.write(block * self.bs, bytes(data))

    # --- ustblok alanlari ---------------------------------------------
    def sb_u32(self, off: int) -> int:
        return struct.unpack_from("<I", self.geo.sb, off)[0]

    def sb_set_u32(self, off: int, value: int) -> None:
        struct.pack_into("<I", self.geo.sb, off, value & 0xFFFFFFFF)

    def sb_u64(self, lo: int, hi: int) -> int:
        value = self.sb_u32(lo)
        if self.geo.incompat & INCOMPAT_64BIT:
            value |= self.sb_u32(hi) << 32
        return value

    def sb_set_u64(self, lo: int, hi: int, value: int) -> None:
        self.sb_set_u32(lo, value)
        if self.geo.incompat & INCOMPAT_64BIT:
            self.sb_set_u32(hi, value >> 32)

    # --- sayaclar -----------------------------------------------------
    @property
    def blocks_count(self) -> int:
        return self.sb_u64(0x04, 0x150)

    def d(self, group: int, field) -> int:
        return desc_field(self.descs[group], field, self.geo.desc_size)

    def set_d(self, group: int, field, value: int) -> None:
        set_desc_field(self.descs[group], field, self.geo.desc_size, value)

    # --- denetim ------------------------------------------------------
    def check_supported(self) -> None:
        g = self.geo
        missing = []
        if g.ro_compat & RO_BIGALLOC:
            missing.append("bigalloc")
        if g.incompat & INCOMPAT_JOURNAL_DEV:
            missing.append(tr("ayri gunluk aygiti"))
        if g.incompat & INCOMPAT_MMP:
            missing.append("mmp")
        if g.compat & COMPAT_SPARSE_SUPER2:
            missing.append("sparse_super2")
        if missing:
            raise ExtResizeError(tr(
                "Bu ext birimi su ozellikleri kullaniyor ve boyutlandirmasi "
                "desteklenmiyor: {}", ", ".join(missing)))
        if g.incompat & INCOMPAT_RECOVER:
            raise ExtResizeError(tr(
                "Birimin gunlugunde islenmemis kayitlar var (temiz "
                "kapatilmamis). Once birimi baglayip duzgun ayirin veya "
                "e2fsck ile onarin."))
        state = struct.unpack_from("<H", g.sb, 0x3A)[0]
        if not state & 0x0001 or state & 0x0002:
            raise ExtResizeError(tr(
                "Birim temiz degil veya hata kaydi var. Boyutlandirmadan once "
                "e2fsck ile denetlenmeli."))

    # --- metaveri yerleri ---------------------------------------------
    def metadata_blocks_in(self, group: int) -> List[int]:
        """Grubun icine dusen tum metaveri bloklari (yerel ofset olarak).

        BLOCK_UNINIT grupta bitmap diskte yoktur; cekirdek onu bu kurala gore
        uretir. Burada ayni kural gerceklenir ve flex_bg ile baska gruplarin
        bu gruba yerlesmis bitmap/inode tablolari da hesaba katilir.
        """
        g = self.geo
        start = g.group_first_block(group)
        size = g.group_block_count(group)
        used = set()
        super_blk, old_start, old_count, new_blk = g.base_meta(group)
        if super_blk is not None and start <= super_blk < start + size:
            used.add(super_blk - start)
        for b in range(old_start, old_start + old_count):
            used.add(b - start)
        if new_blk is not None:
            used.add(new_blk - start)
        itb = g.inode_table_blocks
        for other in range(len(self.descs)):
            for field, length in ((GD_BLOCK_BITMAP, 1), (GD_INODE_BITMAP, 1),
                                  (GD_INODE_TABLE, itb)):
                first = self.d(other, field)
                for b in range(first, first + length):
                    if start <= b < start + size:
                        used.add(b - start)
        return sorted(used)

    def block_bitmap(self, group: int) -> bytearray:
        """Grubun blok bitmap'i; BLOCK_UNINIT ise kurala gore uretilir."""
        g = self.geo
        if self.d(group, GD_FLAGS) & BG_BLOCK_UNINIT and g.csum_kind:
            buf = bytearray(self.bs)
            for i in self.metadata_blocks_in(group):
                buf[i >> 3] |= 1 << (i & 7)
            _set_padding(buf, g.group_block_count(group), self.bs * 8)
            return buf
        return self.read_block(self.d(group, GD_BLOCK_BITMAP))


def _set_padding(buf: bytearray, used_bits: int, total_bits: int) -> None:
    for i in range(used_bits, total_bits):
        buf[i >> 3] |= 1 << (i & 7)


def _clear_bits(buf: bytearray, first: int, last: int) -> None:
    for i in range(first, last):
        buf[i >> 3] &= ~(1 << (i & 7)) & 0xFF


def _count_zero_bits(buf: bytes, nbits: int) -> int:
    full, rest = divmod(nbits, 8)
    ones = sum(bin(b).count("1") for b in buf[:full])
    if rest:

def report(self, msg: str, pct: int) -> None:
    if self.progress:
        self.progress(msg, pct)

# ---- yardimcilar -------------------------------------------------
def in_cut(self, block: int) -> bool:
    return block >= self.target

def inode_offset(self, ino: int) -> int:
    gno, idx = divmod(ino - 1, self.ipg)
    return self.vol.d(gno, GD_INODE_TABLE) * self.bs + idx * self.vol.geo.inode_size

def read_inode(self, ino: int) -> bytearray:
    return bytearray(self.dev.read(self.inode_offset(ino), self.vol.geo.inode_size))

def write_inode(self, ino: int, raw: bytearray, location_ino: Optional[int] = None) -> None:
    self.vol.csum.stamp_inode(ino, raw, self.vol.geo.inode_size)
    self.dev.write(self.inode_offset(location_ino or ino), bytes(raw))

def used_inodes(self) -> List[int]:
    out = []
    v = self.vol
    for gno in range(self.old_groups):
        if v.d(gno, GD_FLAGS) & BG_INODE_UNINIT and v.geo.csum_kind:
            continue
        bm = v.read_block(v.d(gno, GD_INODE_BITMAP))
        limit = self.ipg
        if v.geo.csum_kind:
            limit = self.ipg - v.d(gno, GD_ITABLE_UNUSED)
        for i in range(limit):
            if bm[i >> 3] & (1 << (i & 7)):
                out.append(gno * self.ipg + i + 1)
    return out

def copy_blocks(self, src: int, dst: int, count: int) -> None:
    chunk = max(1, (4 * 1024 * 1024) // self.bs)
    pos = 0
    while pos < count:
        n = min(chunk, count - pos)
        data = self.dev.read((src + pos) * self.bs, n * self.bs)
        self.dev.write((dst + pos) * self.bs, data)
        pos += n

# ---- denetim -----------------------------------------------------
def check(self) -> None:
    g = self.vol.geo
    if g.incompat & (INCOMPAT_INLINE_DATA | INCOMPAT_EA_INODE):
        raise ExtResizeError(tr(
            "inline_data / ea_inode kullanan ext birimi kucultulemez"))
    last = self.keep - 1
    overhead = self.new.base_meta_count(last) + 2 + self.itb
    if last and self.new.group_block_count(last) <= overhead:
        raise ExtResizeError(tr("Son grup metaveri icin cok kucuk"))

# ---- 1) inode yeniden numaralama --------------------------------
def plan_inodes(self, used: List[int]) -> None:
    limit = self.keep * self.ipg
    movers = [ino for ino in used if ino > limit]
    if not movers:
        return
    g = self.vol.geo
    if g.ro_compat & (RO_QUOTA | RO_PROJECT):
        raise ExtResizeError(tr(
            "Kotali (quota) ext biriminde inode tasinamaz; birimi "
            "silinecek gruplarda dosya kalmayacak boyuta kucultun"))
    v = self.vol
    free: List[int] = []
    need = len(movers)
    first_ino = struct.unpack_from("<I", g.sb, 0x54)[0] or 11
    for gno in range(self.keep):
        if len(free) >= need:
            break
        flags = v.d(gno, GD_FLAGS)
        if flags & BG_INODE_UNINIT and g.csum_kind:
            if not flags & BG_INODE_ZEROED:
                _zero_blocks(self.dev, v.d(gno, GD_INODE_TABLE), self.itb, self.bs)
                v.set_d(gno, GD_FLAGS, flags | BG_INODE_ZEROED)
            bm = bytearray(self.bs)
            _set_padding(bm, self.ipg, self.bs * 8)
            v.set_d(gno, GD_FLAGS, v.d(gno, GD_FLAGS) & ~BG_INODE_UNINIT)
            v.set_d(gno, GD_ITABLE_UNUSED, self.ipg)
            v.write_block(v.d(gno, GD_INODE_BITMAP), bm)
            v.csum.stamp_bitmap(v.descs[gno], bm[:(self.ipg + 7) // 8], True,
                                g.desc_size)
        bm = v.read_block(v.d(gno, GD_INODE_BITMAP))
        for i in range(self.ipg):
            ino = gno * self.ipg + i + 1
            if ino < first_ino:
                continue
            if not bm[i >> 3] & (1 << (i & 7)):
                free.append(ino)
                if len(free) >= need:
                    break
    if len(free) < need:
        raise ExtResizeError(tr("Kalan gruplarda yeterli bos inode yok"))
    for old, new in zip(movers, free):
        self.ino_map[old] = new

# ---- 2) kalan gruplarin metaverisi -------------------------------
def relocate_group_metadata(self) -> None:
    v = self.vol
    for gno in range(self.keep):
        for field, count in ((GD_BLOCK_BITMAP, 1), (GD_INODE_BITMAP, 1),
                             (GD_INODE_TABLE, self.itb)):
            first = v.d(gno, field)
            if first + count <= self.target:
                continue
            if count == 1:
                new = self.alloc.alloc()
            else:
                new = self.alloc.alloc_contiguous(count)
            self.copy_blocks(first, new, count)
            for b in range(first, first + count):
                self.alloc.mark(b, False)
            v.set_d(gno, field, new)

# ---- 3) veri bloklari --------------------------------------------
def move_extent_file(self, ino: int, raw: bytearray) -> bool:
    leaves, nodes = read_extents(self.vol, bytes(raw[I_BLOCK:I_BLOCK + 60]))
    needs = any(self.in_cut(b) for b in nodes) or any(
        p + n > self.target for _l, n, p, _u in leaves)
    if not needs:
        self.inode_extents[ino] = nodes
        return False
    new_leaves: List[Tuple[int, int, int, bool]] = []
    for lblk, length, pblk, uninit in leaves:
        done = 0
        while done < length:
            seg_start = pblk + done
            if not self.in_cut(seg_start):
                # kalan bolgede baslayan parca: sinira kadar oldugu gibi
                keep_len = min(length - done, self.target - seg_start)
                new_leaves.append((lblk + done, keep_len, seg_start, uninit))
                done += keep_len
                continue
            start, got = self.alloc.alloc_run(length - done)
            if not uninit:
                self.copy_blocks(seg_start, start, got)
            new_leaves.append((lblk + done, got, start, uninit))
            for b in range(seg_start, seg_start + got):
                self.block_moves[b] = start + (b - seg_start)
            done += got
    new_leaves = _merge_extents(new_leaves)
    for blk in nodes:
        self.alloc.mark(blk, False)
    generation = struct.unpack_from("<I", raw, I_GENERATION)[0]
    final_ino = self.ino_map.get(ino, ino)
    root, new_nodes = build_extent_tree(self.vol, final_ino, generation,
                                        new_leaves, self.alloc.alloc)
    raw[I_BLOCK:I_BLOCK + 60] = root
    self._adjust_iblocks(raw, len(new_nodes) - len(nodes))
    self.inode_extents[ino] = new_nodes
    return True

def _adjust_iblocks(self, raw: bytearray, delta_blocks: int) -> None:
    if not delta_blocks:
        return
    lo = struct.unpack_from("<I", raw, I_BLOCKS)[0]
    hi = struct.unpack_from("<H", raw, 0x74)[0]
    flags = struct.unpack_from("<I", raw, I_FLAGS)[0]
    unit = 1 if (self.huge and flags & HUGE_FILE_FL) else self.bs // 512
    value = ((hi << 32) | lo) + delta_blocks * unit
    struct.pack_into("<I", raw, I_BLOCKS, value & 0xFFFFFFFF)
    struct.pack_into("<H", raw, 0x74, (value >> 32) & 0xFFFF)

def move_indirect_file(self, raw: bytearray) -> bool:
    changed = False

    def relocate(block: int) -> int:
        new = self.alloc.alloc()
        self.copy_blocks(block, new, 1)
        self.block_moves[block] = new
        return new

    def table(block: int, level: int) -> int:
        nonlocal changed
        buf = self.vol.read_block(block)
        dirty = False
        for i in range(self.bs // 4):
            ptr = struct.unpack_from("<I", buf, i * 4)[0]
            if not ptr:
                continue
            new = table(ptr, level - 1) if level > 1 else (
                relocate(ptr) if self.in_cut(ptr) else ptr)
            if new != ptr:
                struct.pack_into("<I", buf, i * 4, new)
                dirty = True
        target = block
        if self.in_cut(block):
            target = self.alloc.alloc()
            self.block_moves[block] = target
            dirty = True
        if dirty:
            changed = True
            self.vol.write_block(target, buf)
        return target

    for i in range(15):
        off = I_BLOCK + i * 4
        ptr = struct.unpack_from("<I", raw, off)[0]
        if not ptr:
            continue
        if i < 12:
            new = relocate(ptr) if self.in_cut(ptr) else ptr
        else:
            new = table(ptr, i - 11)
        if new != ptr:
            struct.pack_into("<I", raw, off, new)
            changed = True
    return changed

def move_xattr_block(self, raw: bytearray) -> bool:
    acl = struct.unpack_from("<I", raw, I_FILE_ACL)[0] | \
        (struct.unpack_from("<H", raw, I_FILE_ACL_HI)[0] << 32)
    if not acl or not self.in_cut(acl):
        return False
    new = self.block_moves.get(acl)
    if new is None:
        new = self.alloc.alloc()
        buf = self.vol.read_block(acl)
        if self.vol.csum.kind == "crc32c":
            crc = raw_crc32c(self.vol.csum.seed, struct.pack("<Q", new))
            crc = raw_crc32c(crc, bytes(buf[:0x10]))
            crc = raw_crc32c(crc, b"\x00\x00\x00\x00")
            crc = raw_crc32c(crc, bytes(buf[0x14:]))
            struct.pack_into("<I", buf, 0x10, crc)
        self.vol.write_block(new, buf)
        self.block_moves[acl] = new
    struct.pack_into("<I", raw, I_FILE_ACL, new & 0xFFFFFFFF)
    struct.pack_into("<H", raw, I_FILE_ACL_HI, new >> 32)
    return True

@staticmethod
def has_block_map(raw: bytes) -> bool:
    mode = struct.unpack_from("<H", raw, I_MODE)[0]
    kind = mode & S_IFMT
    if kind not in (S_IFREG, S_IFDIR, S_IFLNK):
        return False                  # aygit, fifo, soket
    flags = struct.unpack_from("<I", raw, I_FLAGS)[0]
    if kind == S_IFLNK and not flags & EXTENTS_FL:
        size = struct.unpack_from("<I", raw, I_SIZE)[0]
        if size < 60:
            return False              # hizli sembolik bag
    return True

# ---- 4) dizin girisleri ------------------------------------------
def dir_blocks(self, raw: bytes) -> List[Tuple[int, int]]:
    """(mantiksal, fiziksel) — dizin bloklari."""
    flags = struct.unpack_from("<I", raw, I_FLAGS)[0]
    out = []
    if flags & EXTENTS_FL:
        leaves, _n = read_extents(self.vol, bytes(raw[I_BLOCK:I_BLOCK + 60]))
        for lblk, length, pblk, _u in leaves:
            for k in range(length):
                out.append((lblk + k, pblk + k))
        return out
    size = struct.unpack_from("<I", raw, I_SIZE)[0]
    count = (size + self.bs - 1) // self.bs
    ptrs = self._indirect_list(raw, count)
    return [(i, p) for i, p in enumerate(ptrs) if p]

def _indirect_list(self, raw: bytes, count: int) -> List[int]:
    out = list(struct.unpack_from("<12I", raw, I_BLOCK))
    per = self.bs // 4

    def expand(block: int, level: int) -> List[int]:
        if not block:
            return [0] * min(per ** level, max(0, count - len(out)))
        buf = self.vol.read_block(block)
        ptrs = list(struct.unpack_from("<%dI" % per, buf))
        if level == 1:
            return ptrs
        res: List[int] = []
        for p in ptrs:
            res.extend(expand(p, level - 1))
            if len(res) + 12 >= count:
                break
        return res

    for i, level in ((12, 1), (13, 2), (14, 3)):
        if len(out) >= count:
            break
        ptr = struct.unpack_from("<I", raw, I_BLOCK + i * 4)[0]
        out.extend(expand(ptr, level))
    return out[:count]

def fix_directory(self, dir_ino: int, raw: bytes) -> None:
    final_ino = self.ino_map.get(dir_ino, dir_ino)
    generation = struct.unpack_from("<I", raw, I_GENERATION)[0]
    flags = struct.unpack_from("<I", raw, I_FLAGS)[0]

    def stats(self) -> Dict[str, int]:
        return self.fs.stats()

    def flush(self) -> None:
        self.fs.flush()


class ExtAccess(FileSystemAccess):
    """ext2/3/4 icerigine **salt okunur** erisim.

    Yazma yoktur: bir ext birimini degistirmek gunluk (journal) tutarliligi
    gerektirir. Arayuz `writable=False` gordugu icin yazma eylemlerini
    kendiliginden pasifler.
    """

    def __init__(self, view: BlockDevice):
        self.fs = ExtFS(view)
        self.fs_type = "ext"
        self.label = self.fs.label
        self.readable = True
        self.writer = ExtWriter(self.fs)
        self.writable, self._write_reason = self.writer.write_support()

    def listdir(self, path: str = "/") -> List[FileNode]:
        node = self.fs.resolve(path or "/")
        out: List[FileNode] = []
        for entry in self.fs.read_dir(node):
            if entry.name in (".", ".."):
                continue
            try:
                child = self.fs.read_inode(entry.inode)
            except ExtError:
                continue
            child_path = (path.rstrip("/") + "/" + entry.name) if path not in ("", "/") \
                else "/" + entry.name
            attrs = []
            if child.is_symlink:
                try:
                    attrs.append("-> " + self.fs.symlink_target(child))
                except ExtError:
                    attrs.append(tr("bag"))
            if entry.name.startswith("."):
                attrs.append(tr("gizli"))
            out.append(FileNode(
                name=entry.name, path=child_path, is_dir=child.is_dir,
                size=0 if child.is_dir else child.size,
                mtime=ExtFS.timestamp(child.mtime),
                attr_text=" ".join(attrs),
                hidden=entry.name.startswith("."), readonly=True))
        out.sort(key=lambda n: (not n.is_dir, n.name.lower()))
        return out

    def read(self, path: str, max_bytes: int = -1) -> bytes:
        return self.fs.read_data(self.fs.resolve(path), max_bytes)

    def iter_read(self, path: str):
        return self.fs.iter_data(self.fs.resolve(path))

    def extract(self, path: str, dest: str) -> str:
        return self._extract_stream(path, dest)

    @property
    def write_reason(self) -> str:
        return "" if self.writable else self._write_reason

    # -- yazma (ExtWriter uzerinden; her islem e2fsck ile dogrulanmistir) ----
    def write_stream(self, path: str, src, size: int) -> FileNode:
        self.writer.write_stream(path, src, size)
        name = path.replace("\\", "/").rstrip("/").split("/")[-1]
        return FileNode(name=name, path=path, is_dir=False, size=size,
                        mtime=datetime.datetime.now())

    def mkdir(self, path: str) -> None:
        self.writer.mkdir(path)

    def remove(self, path: str, recursive: bool = True) -> None:
        node = self.fs.resolve(path, follow=False)
        if node.is_dir and recursive:
